return items.map((item) => {
  const article = { ...item.json };

  const text = [
    article.title,
    article.summary_raw,
    article.categories,
    article.source,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  let score = 0;
  const reasons = [];

  const addScore = (points, reason, condition) => {
    if (condition) {
      score += points;
      reasons.push(`${reason} (+${points})`);
    }
  };

  const isTrue = (value) =>
    value === true || String(value).toLowerCase() === "true";

  const isRawNvdVulnerability =
    article.source_type === "vulnerability";

  const cvss = Number(article.cvss_score || 0);

  addScore(
    50,
    "CISA Known Exploited Vulnerability",
    isTrue(article.cisa_kev)
  );

  addScore(
    40,
    "Active exploitation",
    isTrue(article.actively_exploited) ||
      /\bactively exploited\b|\bexploited in the wild\b/.test(text)
  );

  addScore(
    35,
    "Zero-day",
    /\bzero[- ]day\b|\b0[- ]day\b/.test(text)
  );

  addScore(
    25,
    "Ransomware",
    /\bransomware\b/.test(text)
  );

  addScore(
    20,
    "Data breach",
    !isRawNvdVulnerability &&
      /\bdata breach\b|\bstolen data\b|\bdata leak\b/.test(text)
  );

  addScore(
    20,
    "DDoS or service disruption",
    !isRawNvdVulnerability &&
      /\bddos\b|\bdenial of service\b|\bservice disruption\b/.test(text)
  );

  addScore(
    15,
    "Malware or phishing activity",
    !isRawNvdVulnerability &&
      /\bmalware\b|\bbotnet\b|\bphishing\b|\binfostealer\b|\bstealer\b/.test(text)
  );

  addScore(
    15,
    "Credential or identity threat",
    !isRawNvdVulnerability &&
      /\bcredential theft\b|\bstolen credentials\b|\bidentity attack\b|\baccount takeover\b/.test(text)
  );

  addScore(
    25,
    "CVSS 9.0 or higher",
    cvss >= 9
  );

  addScore(
    15,
    "SOC or detection relevance",
    !isRawNvdVulnerability &&
      /\bsoc\b|\bdetection\b|\bsiem\b|\bsysmon\b|\bsigma\b|\byara\b|\bioc\b/.test(text)
  );

  addScore(
    10,
    "Microsoft or Windows relevance",
    /\bmicrosoft\b|\bwindows\b|\bactive directory\b|\bentra\b/.test(text)
  );

  addScore(
    10,
    "Linux relevance",
    /\blinux\b|\bubuntu\b|\bdebian\b|\bred hat\b|\brhel\b/.test(text)
  );

  addScore(
    10,
    "Cloud relevance",
    /\baws\b|\bazure\b|\bcloud\b|\bkubernetes\b|\bcontainer\b/.test(text)
  );

  addScore(
    10,
    "MITRE ATT&CK",
    /\bmitre\b|\batt&ck\b/.test(text)
  );

  const published = Date.parse(article.published_at);

  addScore(
    10,
    "Published within 24 hours",
    Number.isFinite(published) &&
      published <= Date.now() &&
      Date.now() - published <= 24 * 60 * 60 * 1000
  );

  if (!article.cve_id) {
    const match = text.match(/\bcve-\d{4}-\d{4,}\b/i);
    article.cve_id = match ? match[0].toUpperCase() : "";
  }

  article.priority_score = Math.min(score, 100);

  article.priority_level =
    article.priority_score >= 75
      ? "CRITICAL"
      : article.priority_score >= 50
        ? "HIGH"
        : article.priority_score >= 25
          ? "MEDIUM"
          : "LOW";

  article.score_reasons = reasons;

  return { json: article };
});

return items.map((item, index) => {
  const story = { ...item.json };

  const text = [
    story.title,
    story.summary_raw,
    story.categories,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  let reportCategory = "General Cybersecurity";

  if (
    story.source_type === "known_exploited_vulnerability" ||
    story.source_type === "vulnerability" ||
    story.cve_id
  ) {
    reportCategory = "Vulnerability";
  } else if (/\bransomware\b/.test(text)) {
    reportCategory = "Ransomware";
  } else if (
    /\bdata breach\b|\bstolen data\b|\bdata leak\b/.test(text)
  ) {
    reportCategory = "Data Breach";
  } else if (
    /\bddos\b|\bdenial of service\b|\bservice disruption\b/.test(text)
  ) {
    reportCategory = "DDoS / Availability";
  } else if (
    /\bmalware\b|\bbotnet\b|\bphishing\b|\binfostealer\b|\bstealer\b/.test(text)
  ) {
    reportCategory = "Threat Activity";
  } else if (
    /\baws\b|\bazure\b|\bcloud\b|\bkubernetes\b|\bcontainer\b/.test(text)
  ) {
    reportCategory = "Cloud Security";
  } else if (
    /\bidentity\b|\bcredential\b|\bactive directory\b|\bentra\b/.test(text)
  ) {
    reportCategory = "Identity Security";
  }

  const cleanSummary = String(story.summary_raw || "")
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  story.rank = index + 1;
  story.report_category = reportCategory;
  story.summary_clean =
    cleanSummary.length > 600
      ? `${cleanSummary.slice(0, 597)}...`
      : cleanSummary;

  return { json: story };
});

const stories = items.map((item) => item.json);

const escapeHtml = (value) =>
  String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");

const safeUrl = (value) => {
  try {
    const url = new URL(String(value || ""));
    return ["http:", "https:"].includes(url.protocol)
      ? url.toString()
      : "#";
  } catch {
    return "#";
  }
};

const getNodeCount = (nodeName, fallback = 0) => {
  try {
    return $(nodeName).all().length;
  } catch {
    return fallback;
  }
};

const takeawayFor = (category) => {
  const takeaways = {
    Vulnerability:
      "Review affected products, confirm exposure, and monitor vendor remediation guidance.",
    "Data Breach":
      "Assess whether your organization or users are exposed and monitor for credential abuse or follow-on fraud.",
    "DDoS / Availability":
      "Review availability controls, upstream protection, alerting, and incident-response procedures.",
    "Threat Activity":
      "Review available indicators and detection opportunities, then compare them with current endpoint and network visibility.",
    Ransomware:
      "Review initial-access controls, backup readiness, endpoint detections, and lateral-movement monitoring.",
    "Cloud Security":
      "Review affected cloud services, identities, permissions, logging, and configuration exposure.",
    "Identity Security":
      "Review authentication logs, privileged access, MFA coverage, and suspicious account activity.",
    "General Cybersecurity":
      "Review the original reporting and determine whether it affects current systems, projects, or learning priorities.",
  };

  return takeaways[category] || takeaways["General Cybersecurity"];
};

const priorityColors = {
  CRITICAL: {
    background: "#fee2e2",
    border: "#dc2626",
    text: "#991b1b",
  },
  HIGH: {
    background: "#ffedd5",
    border: "#ea580c",
    text: "#9a3412",
  },
  MEDIUM: {
    background: "#fef3c7",
    border: "#d97706",
    text: "#92400e",
  },
  LOW: {
    background: "#e0f2fe",
    border: "#0284c7",
    text: "#075985",
  },
};

const reportDate = new Intl.DateTimeFormat("en-CA", {
  timeZone: "America/Toronto",
  year: "numeric",
  month: "long",
  day: "numeric",
  weekday: "long",
}).format(new Date());

const subjectDate = new Intl.DateTimeFormat("en-CA", {
  timeZone: "America/Toronto",
  year: "numeric",
  month: "short",
  day: "numeric",
}).format(new Date());

const mergedCount = getNodeCount(
  "Merge — Fresh Articles",
  stories.length
);

const analyzedCount = getNodeCount(
  "Deduplicate — Current Batch",
  stories.length
);

const duplicatesRemoved = Math.max(
  0,
  mergedCount - analyzedCount
);

const priorityCounts = stories.reduce(
  (counts, story) => {
    const level = story.priority_level || "LOW";
    counts[level] = (counts[level] || 0) + 1;
    return counts;
  },
  { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0 }
);

const categoryCounts = stories.reduce((counts, story) => {
  const category =
    story.report_category || "General Cybersecurity";

  counts[category] = (counts[category] || 0) + 1;
  return counts;
}, {});

const storyCards = stories
  .map((story) => {
    const level = story.priority_level || "LOW";
    const colors =
      priorityColors[level] || priorityColors.LOW;

    const reasons = Array.isArray(story.score_reasons)
      ? story.score_reasons.join(" · ")
      : String(story.score_reasons || "General relevance");

    const cveLine = story.cve_id
      ? `
        <div style="margin-top:8px;">
          <strong>CVE:</strong>
          ${escapeHtml(story.cve_id)}
        </div>
      `
      : "";

    return `
      <div style="
        margin:0 0 22px 0;
        padding:22px;
        background:#ffffff;
        border:1px solid #dbe4ee;
        border-left:6px solid ${colors.border};
        border-radius:10px;
      ">
        <div style="margin-bottom:12px;">
          <span style="
            display:inline-block;
            padding:4px 9px;
            margin-right:8px;
            border-radius:999px;
            background:${colors.background};
            color:${colors.text};
            font-size:12px;
            font-weight:700;
          ">
            ${escapeHtml(level)}
          </span>

          <span style="
            color:#475569;
            font-size:13px;
            font-weight:600;
          ">
            #${escapeHtml(story.rank)}
            · ${escapeHtml(story.report_category)}
            · Score ${escapeHtml(story.priority_score)}/100
          </span>
        </div>

        <h2 style="
          margin:0 0 10px 0;
          color:#0f172a;
          font-size:21px;
          line-height:1.35;
        ">
          ${escapeHtml(story.title)}
        </h2>

        <div style="
          margin-bottom:16px;
          color:#64748b;
          font-size:13px;
        ">
          Source: ${escapeHtml(story.source)}
          · Published: ${escapeHtml(story.published_at)}
        </div>

        <h3 style="
          margin:0 0 6px 0;
          color:#334155;
          font-size:14px;
          text-transform:uppercase;
        ">
          What happened
        </h3>

        <p style="
          margin:0 0 16px 0;
          color:#334155;
          font-size:15px;
          line-height:1.65;
        ">
          ${escapeHtml(
            story.summary_clean ||
              "No summary was supplied by the source."
          )}
        </p>

        <h3 style="
          margin:0 0 6px 0;
          color:#334155;
          font-size:14px;
          text-transform:uppercase;
        ">
          Why it ranked
        </h3>

        <p style="
          margin:0 0 16px 0;
          color:#334155;
          font-size:14px;
          line-height:1.55;
        ">
          ${escapeHtml(reasons)}
        </p>

        <h3 style="
          margin:0 0 6px 0;
          color:#334155;
          font-size:14px;
          text-transform:uppercase;
        ">
          SOC takeaway
        </h3>

        <p style="
          margin:0;
          color:#334155;
          font-size:14px;
          line-height:1.55;
        ">
          ${escapeHtml(
            takeawayFor(story.report_category)
          )}
        </p>

        ${cveLine}

        <div style="margin-top:18px;">
          <a
            href="${escapeHtml(safeUrl(story.url))}"
            style="
              display:inline-block;
              padding:10px 15px;
              border-radius:7px;
              background:#1d4ed8;
              color:#ffffff;
              font-size:14px;
              font-weight:700;
              text-decoration:none;
            "
          >
            Read original source
          </a>
        </div>
      </div>
    `;
  })
  .join("");

const categoryRows = Object.entries(categoryCounts)
  .sort((a, b) => b[1] - a[1])
  .map(
    ([category, count]) => `
      <tr>
        <td style="
          padding:7px 10px;
          border-bottom:1px solid #e2e8f0;
        ">
          ${escapeHtml(category)}
        </td>
        <td style="
          padding:7px 10px;
          border-bottom:1px solid #e2e8f0;
          text-align:right;
          font-weight:700;
        ">
          ${escapeHtml(count)}
        </td>
      </tr>
    `
  )
  .join("");

const html = `
<!doctype html>
<html>
  <body style="
    margin:0;
    padding:0;
    background:#f1f5f9;
    font-family:Arial,Helvetica,sans-serif;
  ">
    <div style="
      max-width:760px;
      margin:0 auto;
      padding:24px 14px 40px;
    ">
      <div style="
        padding:28px;
        background:#0f172a;
        border-radius:12px 12px 0 0;
        color:#ffffff;
      ">
        <div style="
          margin-bottom:6px;
          color:#93c5fd;
          font-size:13px;
          font-weight:700;
          letter-spacing:1.5px;
          text-transform:uppercase;
        ">
          Project Daedalus
        </div>

        <h1 style="
          margin:0 0 8px 0;
          font-size:30px;
          line-height:1.2;
        ">
          Cyber Intelligence Daily
        </h1>

        <div style="
          color:#cbd5e1;
          font-size:15px;
        ">
          ${escapeHtml(reportDate)}
        </div>
      </div>

      <div style="
        padding:22px 28px;
        margin-bottom:22px;
        background:#e2e8f0;
        border-radius:0 0 12px 12px;
      ">
        <div style="
          margin-bottom:12px;
          color:#0f172a;
          font-size:16px;
          font-weight:700;
        ">
          Daily overview
        </div>

        <div style="
          color:#334155;
          font-size:14px;
          line-height:1.8;
        ">
          Sources checked: <strong>8</strong><br>
          Articles analyzed:
          <strong>${escapeHtml(analyzedCount)}</strong><br>
          Duplicates removed:
          <strong>${escapeHtml(duplicatesRemoved)}</strong><br>
          Stories selected:
          <strong>${escapeHtml(stories.length)}</strong><br>
          Critical:
          <strong>${escapeHtml(priorityCounts.CRITICAL)}</strong>
          · High:
          <strong>${escapeHtml(priorityCounts.HIGH)}</strong>
          · Medium:
          <strong>${escapeHtml(priorityCounts.MEDIUM)}</strong>
          · Low:
          <strong>${escapeHtml(priorityCounts.LOW)}</strong>
        </div>
      </div>

      ${storyCards}

      <div style="
        padding:22px;
        background:#ffffff;
        border:1px solid #dbe4ee;
        border-radius:10px;
      ">
        <h2 style="
          margin:0 0 12px 0;
          color:#0f172a;
          font-size:18px;
        ">
          Category summary
        </h2>

        <table style="
          width:100%;
          border-collapse:collapse;
          color:#334155;
          font-size:14px;
        ">
          ${categoryRows}
        </table>
      </div>

      <p style="
        margin:24px 0 0;
        color:#64748b;
        font-size:12px;
        line-height:1.5;
        text-align:center;
      ">
        Generated automatically by Project Daedalus.
        Rankings are deterministic and should support,
        not replace, analyst judgment.
      </p>
    </div>
  </body>
</html>
`;

return [
  {
    json: {
      subject: `🛡️ Cyber Intelligence Daily — ${subjectDate}`,
      html,
      report_date: reportDate,
      sources_checked: 8,
      articles_analyzed: analyzedCount,
      duplicates_removed: duplicatesRemoved,
      articles_selected: stories.length,
      critical_count: priorityCounts.CRITICAL,
      high_count: priorityCounts.HIGH,
      medium_count: priorityCounts.MEDIUM,
      low_count: priorityCounts.LOW,
      category_counts: categoryCounts,
    },
  },
];
